### Tier 3: Production Hardening (30 minutes)
**Complete defense-in-depth strategy**

**3a: Spring Security on Actuator Endpoints**

```java
@Configuration
@EnableWebSecurity
public class ActuatorSecurityConfig {

    @Bean
    public SecurityFilterChain actuatorSecurityFilterChain(HttpSecurity http) throws Exception {
        http
            // SECURITY: Require authentication for all actuator endpoints
            .authorizeHttpRequests(authz -> authz
                .requestMatchers("/actuator/**").hasRole("ADMIN")
                .requestMatchers("/actuator/gateway/**").hasRole("GATEWAY_ADMIN")
                .requestMatchers("/gateway/**").denyAll()  // Block any gateway admin endpoints on main port
                .anyRequest().permitAll()
            )
            // SECURITY: Use HTTPS-only for actuator (no HTTP fallback)
            .requiresChannel(channel -> channel
                .requestMatchers("/actuator/**").requiresSecure()
            )
            // SECURITY: Enable CSRF protection for state-changing operations
            .csrf(csrf -> csrf
                .ignoringRequestMatchers("/actuator/gateway/refresh")  // Optional: if refresh is automated
            )
            // SECURITY: Add security headers
            .headers(headers -> headers
                .frameOptions().deny()  // Prevent clickjacking
                .xssProtection().and()
                .contentSecurityPolicy("default-src 'none'")
            )
            .sessionManagement(session -> session
                .sessionFixationProtection(SessionFixationProtectionStrategy.MIGRATEWINDOWS)
                .sessionConcurrency(concurrency -> concurrency
                    .maximumSessions(1)  // One session per admin user
                    .expiredUrl("/login?expired")
                )
            );

        return http.build();
    }

    @Bean
    public UserDetailsService userDetailsService() {
        // SECURITY: Store admin credentials securely (NOT hardcoded)
        // Use external secret management: HashiCorp Vault, AWS Secrets Manager, etc.
        UserDetails admin = User.builder()
            .username("gateway-admin")
            // Password from environment variable or secrets manager
            .password(passwordEncoder().encode(System.getenv("GATEWAY_ADMIN_PASSWORD")))
            .roles("GATEWAY_ADMIN")
            .accountLocked(false)
            .accountExpired(false)
            .credentialsExpired(false)
            .disabled(false)
            .build();

        return new InMemoryUserDetailsManager(admin);
    }

    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder(12);
    }
}
```

**3b: Custom Filter to Block Malicious SpEL Patterns**

```java
@Component
public class SpELInjectionDetectionFilter extends OncePerRequestFilter {

    private static final List<String> DANGEROUS_SPEL_PATTERNS = Arrays.asList(
        "T(java.lang.Runtime)",
        "T(java.lang.ProcessBuilder)",
        "getRuntime",
        ".exec(",
        "Runtime.getRuntime",
        "ProcessBuilder",
        "java.nio.file.Files",
        "FileWriter",
        "ObjectInputStream",
        "@",  // Bean access
        "#_",  // Private variable access
        "#{",  // SpEL expression start
        "?[",  // Query selection
        ".["   // Property access chain
    );

    private static final MeterRegistry meterRegistry = new SimpleMeterRegistry();
    private static final Counter spelAttempts = Counter.builder("spel_injection.attempts")
        .description("SpEL injection attack attempts detected")
        .register(meterRegistry);

    @Override
    protected void doFilterInternal(HttpServletRequest request, 
                                   HttpServletResponse response, 
                                   FilterChain filterChain) 
            throws ServletException, IOException {

        // Only check actuator gateway endpoints
        if (!request.getRequestURI().contains("/actuator/gateway")) {
            filterChain.doFilter(request, response);
            return;
        }

        // Check request body for SpEL patterns
        String body = getRequestBody(request);

        for (String pattern : DANGEROUS_SPEL_PATTERNS) {
            if (body.contains(pattern)) {
                logSecurityAlert("SPEL_INJECTION_DETECTED", 
                    request.getRemoteAddr(), 
                    request.getRequestURI(),
                    pattern);

                spelAttempts.increment();

                response.setStatus(HttpServletResponse.SC_FORBIDDEN);
                response.getWriter().write("{\"error\":\"Malicious request detected\"}");
                return;
            }
        }

        filterChain.doFilter(request, response);
    }

    private String getRequestBody(HttpServletRequest request) throws IOException {
        // Wrap request to allow multiple reads of body
        if (request instanceof ContentCachingRequestWrapper) {
            return new String(((ContentCachingRequestWrapper) request).getContentAsByteArray());
        }
        return "";
    }

    private void logSecurityAlert(String eventType, String sourceIp, String uri, String pattern) {
        String alert = String.format(
            "SECURITY_ALERT event=%s source_ip=%s uri=%s pattern=%s timestamp=%s",
            eventType, sourceIp, uri, pattern, Instant.now()
        );
        System.err.println(alert);  // To SIEM via stderr
    }
}
```

**3c: Monitoring & Alerting**

```yaml
# prometheus.yml
scrape_configs:
  - job_name: 'spring-cloud-gateway'
    static_configs:
      - targets: ['localhost:8080']
    metrics_path: '/actuator/prometheus'
```

```yaml
# Alert rules (alert.rules.yml)
groups:
  - name: spring_cloud_gateway
    rules:
      - alert: ActuatorEndpointAccess
        expr: rate(http_server_requests_seconds_count{uri=~"/actuator/.*"}[5m]) > 0
        annotations:
          summary: "Actuator endpoint accessed"
          severity: "WARNING"
          action: "Review logs for unauthorized access"

      - alert: SpELInjectionAttempt
        expr: rate(spel_injection_attempts[1m]) > 0
        for: 1m
        annotations:
          summary: "SpEL injection attack detected"
          severity: "CRITICAL"
          action: "Immediate incident response - potential RCE attempt"

      - alert: GatewayRefreshEndpointCalled
        expr: rate(http_server_requests_seconds_count{uri="/actuator/gateway/refresh",method="POST"}[5m]) > 0
        annotations:
          summary: "Gateway refresh triggered"
          severity: "INFO"
          action: "Verify this was authorized maintenance"
```

**3d: Incident Response Automation**

```java
@Component
public class RCEIncidentResponder {

    @Autowired
    private AlertingService alerting;

    @Autowired
    private AuditService audit;

    // When SpEL injection detected:
    public void handleRCEAttempt(String sourceIp, String payload) {
        // 1. Block IP immediately
        firewall.blockIp(sourceIp, Duration.ofHours(24));

        // 2. Alert security team
        alerting.sendToSlack(
            "🚨 CRITICAL: RCE Attempt Detected\n" +
            "Source: " + sourceIp + "\n" +
            "Gateway: " + System.getenv("HOSTNAME") + "\n" +
            "Status: BLOCKED"
        );
        alerting.sendToPageDuty("RCE_ATTEMPT", "P1");

        // 3. Preserve evidence
        audit.logSecurityIncident(
            "RCE_ATTEMPT",
            sourceIp,
            payload,
            "BLOCKED_BY_DETECTION_FILTER"
        );

        // 4. Optional: Isolate gateway from network
        // orchestration.isolateService("spring-cloud-gateway");
    }
}
```

