@Configuration
@EnableGlobalMethodSecurity(prePostEnabled = true, securedEnabled = true)
public class AuditLoggingConfig {

    @Bean
    public AuditEventRepository auditEventRepository() {
        // Log all actuator access to secure audit trail
        return new InMemoryAuditEventRepository();
    }
}

// Log all gateway route modifications
@Component
@Aspect
public class GatewayModificationAuditor {

    @Around("execution(* org.springframework.cloud.gateway.actuate.GatewayController.*(..))")  
    public Object auditGatewayModification(ProceedingJoinPoint joinPoint) throws Throwable {
        String methodName = joinPoint.getSignature().getName();
        Object[] args = joinPoint.getArgs();

        // Log BEFORE execution
        AuditEvent.log("GATEWAY_MODIFICATION_ATTEMPTED", 
            methodName, 
            args);

        try {
            Object result = joinPoint.proceed();

            // Log SUCCESS
            AuditEvent.log("GATEWAY_MODIFICATION_SUCCESS", 
                methodName, 
                args);

            return result;
        } catch (Exception e) {
            // Log FAILURE
            AuditEvent.logError("GATEWAY_MODIFICATION_FAILED", 
                methodName, 
                e.getMessage());
            throw e;
        }
    }
}
